-- Phase 9: Safety ID architecture (expand → migrate; nothing is dropped or renamed).
--
-- The Emergency Safety ID becomes the owner of the QR token, Activation PIN, ownership,
-- emergency sharing, scans and QR risk. Helmets keep product identity, lifecycle and warranty.
-- Old helmet QR/PIN columns and helmet_* emergency/analytics tables stay for rollback and are
-- removed only by a later cleanup release. See docs/SAFETY-ID-MIGRATION.md.
--
-- Part 1 (generated by prisma migrate diff): additive DDL. The only ALTERs relax NOT NULL on
-- helmets.public_token, helmets.activation_pin_hash and helmet_scans.helmet_id.

-- CreateEnum
CREATE TYPE "SafetyIdStatus" AS ENUM ('GENERATED', 'PRINTED', 'ACTIVATED', 'ACTIVE', 'DEACTIVATED', 'REPLACED');

-- CreateEnum
CREATE TYPE "SafetyIdOwnershipSource" AS ENUM ('ACTIVATION', 'TRANSFER', 'ADMIN_ASSIGNMENT', 'MIGRATION');

-- CreateEnum
CREATE TYPE "SafetyIdBatchMode" AS ENUM ('STANDALONE', 'HELMET_LINKED');

