-- ─────────────── Part 2: invariants not expressible in schema.prisma ───────────────

-- One current helmet link per Safety ID and per helmet; history rows keep ended_at.
CREATE UNIQUE INDEX "safety_id_helmet_links_one_current_per_safety_id"
  ON "safety_id_helmet_links"("safety_id") WHERE "ended_at" IS NULL;
CREATE UNIQUE INDEX "safety_id_helmet_links_one_current_per_helmet"
  ON "safety_id_helmet_links"("helmet_id") WHERE "ended_at" IS NULL;

-- One ACTIVE owner per Safety ID; a period is open exactly while ACTIVE.
CREATE UNIQUE INDEX "safety_id_ownerships_one_active"
  ON "safety_id_ownerships"("safety_id") WHERE "status" = 'ACTIVE';
ALTER TABLE "safety_id_ownerships"
  ADD CONSTRAINT "safety_id_ownerships_period_consistent"
  CHECK (("status" = 'ACTIVE') = ("ended_at" IS NULL));

-- One pending Transfer Code per Safety ID.
CREATE UNIQUE INDEX "safety_id_transfers_one_pending"
  ON "safety_id_transfers"("safety_id") WHERE "status" = 'PENDING';

-- One active risk signal per (Safety ID, type), as for helmets in Phase 6.
CREATE UNIQUE INDEX "safety_id_risk_signals_one_active"
  ON "safety_id_risk_signals"("safety_id", "type") WHERE "status" = 'ACTIVE';

-- Formats checked at the database level as well.
ALTER TABLE "safety_ids"
  ADD CONSTRAINT "safety_ids_code_format"
  CHECK ("safety_code" ~ '^SI-[23456789ABCDEFGHJKMNPQRSTUVWXYZ]{4}-[23456789ABCDEFGHJKMNPQRSTUVWXYZ]{4}$');

CREATE SEQUENCE "safety_id_batch_code_seq" START WITH 1 INCREMENT BY 1 NO CYCLE;

-- ─────────────── Part 3: backfill every Phase 8 QR identity ───────────────
-- Each QR-bearing helmet becomes exactly one Safety ID with THE SAME id (UUID) and THE SAME
-- public token. Reusing the id keeps scans, risk rows and the PIN escrow (AES-GCM associated
-- data = this id) valid without re-encryption. Every statement is idempotent.

-- 3.1 Safety IDs. Code = 'SI-' + Helmet ID body (the check symbol covers only the body, so the
-- code is valid and unique). Status reflects activation + sharing only; physical lifecycle
-- (lost/stolen/damaged/recalled/replaced/deactivated) stays on the linked helmet and is applied
-- by the public page exactly as before.
INSERT INTO "safety_ids" (
  "id", "safety_code", "public_token", "status",
  "activation_pin_hash", "activation_pin_used", "activation_attempts", "activation_locked_until",
  "qr_integrity_status", "qr_integrity_note", "qr_integrity_changed_at",
  "activated_at", "created_at", "updated_at")
SELECT
  h."id",
  'SI-' || substr(h."helmet_code", 4),
  h."public_token",
  (CASE
     WHEN h."activated_at" IS NULL AND NOT h."activation_pin_used" THEN
       CASE WHEN h."status" = 'GENERATED' THEN 'GENERATED' ELSE 'PRINTED' END
     WHEN EXISTS (
       SELECT 1 FROM "helmet_ownerships" o
       JOIN "helmet_emergency_settings" s ON s."helmet_id" = o."helmet_id" AND s."user_id" = o."user_id"
       WHERE o."helmet_id" = h."id" AND o."status" = 'ACTIVE' AND s."enabled") THEN 'ACTIVE'
     ELSE 'ACTIVATED'
   END)::"SafetyIdStatus",
  h."activation_pin_hash", h."activation_pin_used", h."activation_attempts", h."activation_locked_until",
  h."qr_integrity_status", h."qr_integrity_note", h."qr_integrity_changed_at",
  h."activated_at", h."created_at", CURRENT_TIMESTAMP
FROM "helmets" h
WHERE h."public_token" IS NOT NULL AND h."activation_pin_hash" IS NOT NULL
ON CONFLICT ("id") DO NOTHING;

-- 3.2 PIN escrow: ciphertext copied unchanged (AAD = helmet id = Safety ID id).
INSERT INTO "safety_id_activation_secrets" ("safety_id", "pin_ciphertext", "created_at", "updated_at")
SELECT s."helmet_id", s."pin_ciphertext", s."created_at", s."updated_at"
FROM "helmet_activation_secrets" s
JOIN "safety_ids" si ON si."id" = s."helmet_id"
ON CONFLICT ("safety_id") DO NOTHING;

-- 3.3 Current link Safety ID ↔ helmet.
INSERT INTO "safety_id_helmet_links" ("id", "safety_id", "helmet_id", "started_at", "reason", "created_at")
SELECT gen_random_uuid(), si."id", si."id", si."created_at", 'MIGRATION', CURRENT_TIMESTAMP
FROM "safety_ids" si
JOIN "helmets" h ON h."id" = si."id"
WHERE NOT EXISTS (SELECT 1 FROM "safety_id_helmet_links" l WHERE l."safety_id" = si."id");

-- 3.4 Ownership history (all periods, so the QR's history is complete).
INSERT INTO "safety_id_ownerships" (
  "id", "safety_id", "user_id", "status", "source", "started_at", "ended_at", "end_reason",
  "created_at", "updated_at")
SELECT gen_random_uuid(), o."helmet_id", o."user_id", o."status", 'MIGRATION',
       o."activated_at", o."ended_at", o."end_reason", o."created_at", o."updated_at"
FROM "helmet_ownerships" o
JOIN "safety_ids" si ON si."id" = o."helmet_id"
WHERE NOT EXISTS (SELECT 1 FROM "safety_id_ownerships" so WHERE so."safety_id" = o."helmet_id");

-- 3.5 Emergency sharing switches: enabled state copied exactly (never switched on or off here).
INSERT INTO "safety_id_emergency_settings" (
  "id", "safety_id", "user_id", "enabled", "confirmed_at", "created_at", "updated_at")
SELECT gen_random_uuid(), e."helmet_id", e."user_id", e."enabled", e."confirmed_at", e."created_at", e."updated_at"
FROM "helmet_emergency_settings" e
JOIN "safety_ids" si ON si."id" = e."helmet_id"
ON CONFLICT ("safety_id", "user_id") DO NOTHING;

-- 3.6 Scans: attach to the Safety ID (same id); rows are not duplicated.
UPDATE "helmet_scans" SET "safety_id" = "helmet_id"
WHERE "safety_id" IS NULL AND "helmet_id" IN (SELECT "id" FROM "safety_ids");

-- 3.7 Daily scan aggregates.
INSERT INTO "safety_id_scan_daily" (
  "id", "date", "safety_id", "total_scans", "emergency_scans", "verification_scans",
  "activation_scans", "bot_scans", "unique_ip_hashes", "distinct_device_categories",
  "last_scan_at", "created_at", "updated_at")
SELECT gen_random_uuid(), d."date", d."helmet_id", d."total_scans", d."emergency_scans",
       d."verification_scans", d."activation_scans", d."bot_scans", d."unique_ip_hashes",
       d."distinct_device_categories", d."last_scan_at", d."created_at", d."updated_at"
FROM "helmet_scan_daily" d
JOIN "safety_ids" si ON si."id" = d."helmet_id"
ON CONFLICT ("safety_id", "date") DO NOTHING;

-- 3.8 Risk assessments and signals.
INSERT INTO "safety_id_risk_assessments" (
  "safety_id", "risk_level", "risk_score", "reasons", "evaluated_at", "first_detected_at",
  "last_detected_at", "resolved_at", "resolution_reason")
SELECT a."helmet_id", a."risk_level", a."risk_score", a."reasons", a."evaluated_at",
       a."first_detected_at", a."last_detected_at", a."resolved_at", a."resolution_reason"
FROM "helmet_risk_assessments" a
JOIN "safety_ids" si ON si."id" = a."helmet_id"
ON CONFLICT ("safety_id") DO NOTHING;

INSERT INTO "safety_id_risk_signals" (
  "id", "safety_id", "type", "severity", "status", "window_start", "window_end",
  "observed_value", "threshold_value", "first_detected_at", "last_detected_at", "cleared_at",
  "metadata", "created_at", "updated_at")
SELECT r."id", r."helmet_id", r."type", r."severity", r."status", r."window_start", r."window_end",
       r."observed_value", r."threshold_value", r."first_detected_at", r."last_detected_at",
       r."cleared_at", r."metadata", r."created_at", r."updated_at"
FROM "helmet_risk_signals" r
JOIN "safety_ids" si ON si."id" = r."helmet_id"
ON CONFLICT ("id") DO NOTHING;

-- 3.9 Alerts and reports keep their rows; they now also point at the Safety ID. Helmet-scoped
-- dedup keys become Safety-ID-scoped (same UUID), so open alerts keep deduplicating.
UPDATE "risk_alerts" SET "safety_id" = "helmet_id"
WHERE "safety_id" IS NULL AND "helmet_id" IN (SELECT "id" FROM "safety_ids");
UPDATE "risk_alerts" SET "dedup_key" = 'safety:' || substr("dedup_key", 8)
WHERE "dedup_key" LIKE 'helmet:%';

UPDATE "product_reports" SET "safety_id" = "helmet_id"
WHERE "safety_id" IS NULL AND "helmet_id" IN (SELECT "id" FROM "safety_ids");
